// Strategy lessons are scoped to legal, named example positions, not engine evaluations.
import {Chess} from './chess.js';
import {guides} from './guides.js';
import {extra} from './strategy-extra.js';
import {specs,exampleLines} from './strategy-map.js';
import {overrides} from './strategy-overrides.js';
const split=s=>s.split('|');
export const P={...extra};
function profile(id,title,purpose,structure,ideas,pieces,targets,counters,white,black){P[id]={id,title,purpose,structure,ideas:split(ideas),pieces:split(pieces),targets:split(targets),counters:split(counters),plans:[white.split('→'),black.split('→')]};}
profile('quiet','e4–e5 · 전개와 중앙 긴장','양쪽이 e폰을 직접 중앙에 놓고, 전개를 마친 뒤 d폰 돌파로 활동을 얻는 열린 게임 계열입니다. d3·d6가 유지되면 당장은 조용한 기동전이며 중앙이 열릴 때 전술의 비중이 커집니다.','e4–e5가 맞서고 d3·d6가 받치는 경우 공간은 대체로 균형입니다. e폰은 중앙 거점이지만 d폰 수비에 의존합니다. 아직 고립폰이나 더블폰이 필수로 생기지는 않습니다. 백 d4 / 흑 …d5가 구조를 여는 핵심이며 준비 없이 밀면 중앙 폰을 잃을 수 있습니다.','중앙 돌파: d4 / …d5는 폰 수비 사슬을 없애 비숍과 룩을 활성화합니다.|전개 우선: 중앙이 열리면 한 템포가 체크·핀으로 바뀌므로 킹을 먼저 안전하게 둡니다.|긴장 유지: 중앙을 바로 교환하면 상대의 전개도 편해질 수 있어 기물 배치 후 교환을 고릅니다.','백: c4/b3 밝은 칸 비숍은 중앙과 f7을 연결합니다. d3로 d2가 비어 c1 어두운 칸 비숍은 e3·g5 등의 전개 경로를 얻습니다. 나이트는 d4를 돕고 룩은 중앙 교환 후 e/d열을 활용합니다.|흑: c5 어두운 칸 비숍은 f2/d4를 봅니다. …d6로 d7이 비어 c8 밝은 칸 비숍의 …Be6/…Bg4 경로가 열립니다. …d5 교환 뒤에는 비숍의 대각선과 중앙 룩의 활동이 커집니다.','백: e5폰을 Nf3와 룩의 중앙 압력으로 겨냥 → 흑의 d6 수비를 묶음 → d4로 선을 열어 전개 우위를 얻습니다.|흑: e4폰을 …Nf6와 중앙 룩으로 압박 → 백의 공격 말이 수비에 남게 함 → …d5로 중앙을 해소합니다.','흑의 …d5: 백의 측면 공격을 중앙 교환으로 늦추려 합니다. 무시하면 e4가 공격받고 비숍의 대각선이 열립니다.|백의 d4: 흑의 e5 거점을 흔듭니다. 흑은 교환 후 전개하거나 중앙을 지켜야 하며 폰만 지키다 뒤처지면 열린 중앙에서 킹이 노출됩니다.','e4–e5 긴장→전개 안 된 나이트·c1 비숍 개선→d4를 기물로 준비→e5와 열린 중앙→돌파를 막는 중앙 수비 말 교환→활동적인 공격 비숍의 이유 없는 교환 피하기→안전한 킹과 열린 선의 활동','e4–e5 긴장→c8 비숍·b8 나이트 개선→…d5 준비→e4와 중앙 기물→백의 강한 중앙 공격 말 교환→유일한 활성 비숍을 수동 나이트와 교환하지 않기→중앙 균형과 자유로운 기물');
profile('scotch','스카치 · 중앙 교환','백은 3.d4로 e5 수비를 즉시 시험하고 중앙을 열어 빠른 활동을 얻습니다. 흑은 폰을 되돌려주더라도 d4 나이트에 템포를 얻고 동등한 전개를 목표로 합니다. 열린 선에서 구체적인 전술과 전개 순서가 중요합니다.','백 d폰과 흑 e폰이 사라져 백 e4폰이 공간 거점이 됩니다. d열은 양쪽 d폰의 위치에 따라 반열림/열림이 바뀌며 흑 d7폰이 남은 예시에서는 완전한 열린 열이 아닙니다. …d5는 e4를 공격하고 비숍을 풀어 주는 해방 수입니다.','d4 나이트 압박: 흑의 …Bc5·…Qf6는 전개하면서 중앙 말을 겨냥합니다.|e4 유지: 백의 공간 거점이므로 전개와 수비를 함께 해야 합니다.|…d5 해방: 충분히 준비되면 백의 공간 이점을 줄입니다.','백: d4 나이트는 중앙에서 활동하지만 흑 비숍·퀸의 공격 대상입니다. e4폰은 밝은 칸 비숍의 대각선 일부를 제한할 수 있어 배치를 계산합니다. 중앙 룩은 돌파 후 가치가 커집니다.|흑: c5 비숍은 d4와 f2를 겨냥합니다. 나이트를 빠르게 전개하고 c8 비숍을 …d5로 풀면 좁은 공간의 문제가 줄어듭니다.','백: e4 공간을 바탕으로 비숍·룩을 전개 → 열린 중앙의 흑 킹과 전개 지연을 겨냥 → 주도권 확보.|흑: d4 나이트를 Bc5·Qf6로 공격 → 백의 중앙 배치에 템포 획득 → …d5로 공간 균형 회복.','흑의 …Bc5: d4 나이트를 공격해 백의 자유로운 전개를 막습니다. 수비 없이 다른 수를 두면 중앙 기물을 잃습니다.|흑의 …Nf6: e4를 공격합니다. 백은 e5 또는 Nxc6 등 다른 구조를 선택할 수 있으며 이 갈래의 계획을 현재 …Bc5 예시와 섞지 않습니다.','중앙 교환과 e4 거점→d4 나이트 수비·비숍 전개→상황에 맞는 e5 준비→중앙 킹·전개 약점→압박하는 흑 비숍을 유리한 조건에서 교환→중앙 거점 없이 공격 말만 교환하지 않기→활동적인 말과 안전한 e4폰','백 e4 공간→왕측 전개와 캐슬링→…d5 준비→d4 나이트·e4폰→백의 활동적인 중앙 말 교환→c5 비숍의 템포를 헛되이 포기하지 않기→중앙 공간 차이를 해소한 국면');
profile('french-chain','프렌치 · 닫힌 중앙','백은 e5로 공간을 확보하고 킹사이드 활동을 준비합니다. 흑은 e6–d5 사슬로 버티면서 …c5로 d4 밑부분, …f6로 e5 앞부분을 공격합니다. 닫힌 반열린 게임에서 공간과 반격의 균형을 다루는 구조입니다.','백 d4–e5와 흑 e6–d5 사슬이 중앙을 잠급니다. 백은 킹사이드 공간, 흑은 퀸사이드 반격 여지를 갖습니다. d4가 백 사슬의 밑부분이며 e6은 흑 c8 비숍을 제한합니다. 백 c3가 있으면 d4를 받치지만 c3 나이트 전개가 막힙니다. …c5/…f6가 열릴 때마다 계획을 다시 평가합니다.','사슬 밑부분 d4: …c5·…Nc6·…Qb6가 수비를 과부하시키려 합니다.|사슬 앞부분 e5: …f6는 백의 공간 거점을 제거하지만 흑 킹 주변도 열므로 전개를 먼저 확인합니다.|백의 공간: 기물을 왕측에 모을 시간이 생기지만 중앙 수비를 버리고 공격할 권리는 아닙니다.','백: d4/e5는 어두운 칸 폰이므로 c1 어두운 칸 비숍은 사슬 안에 머물면 제한될 수 있어 사슬 밖 전개를 찾습니다. 밝은 칸 비숍은 d3에서 h7을 볼 수 있지만 d4 수비·중앙 교환을 계산해야 합니다. Nf3는 d4를 지킵니다.|흑: c8 밝은 칸 비숍은 e6–d5에 갇히기 쉬워 …b6–Ba6 교환이나 중앙 해방을 찾습니다. c6 나이트·b6 퀸은 d4를 압박합니다. 닫힌 중앙에서는 나이트의 우회 가치가 큽니다.','백: 킹사이드 공간 → Bd3·Nf3·퀸으로 h7 등 킹 주변을 겨냥 → 중앙이 안전할 때 공격 선 확보.|흑: d4를 c5폰·Nc6·Qb6로 압박 → 백 사슬의 밑부분 제거 → e5의 지지 감소와 중앙 활동 획득.','흑의 …c5: d4를 공격해 왕측 공격을 늦춥니다. 백이 무시하면 중앙 폰 손실이나 c열 개방으로 퀸사이드 약점이 생깁니다.|흑의 …f6: e5를 교환해 공간을 줄입니다. 백은 유지·교환·전진을 계산해야 하며 왕측 선이 열리면 양쪽 킹 안전이 달라집니다.','닫힌 d4–e5 사슬→왕측 나이트·밝은 칸 비숍의 자리 개선→중앙이 견디면 f5 등 왕측 돌파 검토→흑 킹과 중앙 수비 말→활동을 막는 흑 수비 나이트 교환→왕측 공격 비숍을 대가 없이 교환하지 않기→유지된 중앙과 왕측 주도권','e6–d5 사슬과 공간 부족→c8 비숍·b8 나이트 개선→…c5 먼저, 조건이 맞으면 …f6→d4 다음 e5→나쁜 c8 비숍을 활성 백 비숍과 교환→중앙 압박 말을 먼저 없애지 않기→백 중앙을 해체하고 활동이 열린 국면');
profile('french-ex','프렌치 · 교환 대칭','백은 e폰을 교환해 프렌치의 닫힌 사슬 싸움을 피합니다. 양쪽은 대칭 d폰과 열린 e열에서 전개·파일 통제·유리한 교환으로 작은 차이를 만들려 합니다. 대칭 구조가 강제 무승부를 의미하지는 않습니다.','양쪽 e폰이 없어 e열이 열리고 d4/d5가 맞섭니다. 공간은 균형이며 e6이 없어 흑 c8 비숍의 기존 제한이 풀립니다. c4/…c5를 추가하면 대칭이 깨지고 고립 d폰 구조가 생길 수 있으므로 별도 판단이 필요합니다.','열린 e열: 룩의 진입 칸을 통제하며 파일을 다툽니다.|대칭 깨기: c4/…c5는 d폰을 흔들지만 교환 뒤 고립폰 비용을 계산합니다.|기물 배치 차이: 같은 폰 구조여도 핀·캐슬링 방향·전개 속도가 공격 기회를 만듭니다.','백: e1 룩이 열린 e열을 이용합니다. 비숍은 e폰 장애 없이 활동하며 d3 비숍은 h7을 보지만 중앙의 교환과 핀을 확인해야 합니다.|흑: c8 비숍은 프렌치 어드밴스보다 자유롭습니다. e열 룩과 중앙 나이트가 핵심이며 대칭 구조만 믿고 상대의 핀을 방치하지 않습니다.','백: 열린 e열 → 룩을 e1에 두고 진입 칸 확보 → 상대 진영 침투와 전개 압박.|흑: 같은 e열·백 중앙 → …Re8과 중앙 기물 → 파일 균형 또는 백의 약해진 고립폰 압박.','…c5 / c4: 대칭을 깨고 중앙을 교환하려 합니다. 무시하면 d폰 수비가 부담되며 교환 후 새로운 고립폰 구조를 확인해야 합니다.|상대의 e열 중복: 열린 파일을 장악하려 합니다. 룩 교환이나 진입 칸 수비를 놓치면 2·7랭크 침투가 가능합니다.','대칭 d폰·열린 e열→퀸측 기물 전개→c4는 고립폰 결과까지 계산→e열 진입 칸→상대의 활성 파일 룩 교환→유일한 활동 룩을 수동 말과 바꾸지 않기→파일 통제와 안전한 중앙','대칭 d폰·열린 e열→c8 비숍·b8 나이트 전개→…c5는 중앙 수비 후 검토→e열과 d4→백의 활성 중앙 말 교환→전개를 해소하는 비숍을 이유 없이 잃지 않기→활동이 균형인 중앙');
profile('iqp-white','백의 고립 d폰 · 활동과 봉쇄','백은 고립 d폰을 감수하고 중앙 공간과 열린 선에서 기물 활동을 얻습니다. 흑은 d5를 봉쇄하고 기물을 교환해 장기적인 폰 약점을 드러내려 합니다. 활발한 미들게임과 약한 엔드게임 가능성을 함께 평가합니다.','백 c/e폰이 교환된 뒤 d4폰에 인접 폰이 없어 고립폰이 됩니다. d4는 e5/c5를 통제하는 공간 거점이지만 폰으로 지킬 수 없습니다. 백 d5 돌파는 약점을 해소하고, 흑은 d5 봉쇄로 돌파를 막습니다. 대표 그림이 아직 교환 전이면 고립폰은 가능성이지 현재 사실이 아닙니다.','d5 돌파: 고립폰을 없애며 룩·비숍 선을 엽니다. 교환 후 기물 손실이 없는지 계산합니다.|e5 전초기지: d4가 나이트를 지원해 왕측 활동을 강화합니다.|흑의 봉쇄와 교환: d5 나이트가 폰을 멈추고 기물 감소가 폰 약점을 키웁니다.','백: Ne5와 Bd3/Bc4, 중앙 룩이 d4 공간을 활용합니다. 퀸은 공격 말과 협력하고 룩은 d/e열에서 돌파를 지원합니다. 많은 활동 말이 있어야 고립폰의 보상이 유지됩니다.|흑: d5 나이트는 폰에 쫓기지 않는 봉쇄 말이 될 수 있습니다. 어두운 칸 비숍과 퀸은 d4 수비를 공격합니다. 활동 말의 교환은 대체로 흑의 장기 목표를 돕습니다.','백: 킹사이드 킹 → Ne5·비숍·퀸의 협력과 중앙 돌파 → 열린 선의 공격.|흑: d4 고립폰 → d5 봉쇄 나이트와 d열 중기물 → 폰 획득 또는 유리한 엔드게임.','흑의 …Nd5 봉쇄: 백의 d5를 막습니다. 백은 봉쇄 말을 교환하거나 활동을 다른 선으로 옮겨야 하며 방치하면 d4가 고정 약점입니다.|백의 d5 돌파: 흑의 봉쇄 계획을 무너뜨립니다. 흑은 중앙 교환 뒤 전술을 계산하고 기물 활동을 따라가야 합니다.','고립 d4와 활동 선→나이트를 e5에·룩을 중앙에→d5 준비→왕측 킹·중앙 방어 말→d5 봉쇄 말 교환→활동적인 소기물을 일괄 교환하지 않기→약점을 해소한 공격적 중앙','d4 약점→나이트를 d5 봉쇄 칸에→…e5 등은 봉쇄가 깨지지 않을 때만→d4→백의 공격 소기물·퀸 교환 검토→좋은 봉쇄 나이트를 성급히 교환하지 않기→고립폰을 압박하는 엔드게임');
profile('iqp-black','흑의 고립 d폰 · 활동과 봉쇄','흑은 중앙 …c5 교환으로 공간과 기물 활동을 얻는 대신 고립 d폰 가능성을 받아들입니다. 백은 d4 봉쇄·중앙 압력·교환으로 구조적 이점을 살리려 합니다. 현재 교환 정도에 따라 고립폰이 아직 완성되지 않았을 수 있습니다.','흑 c/e폰이 사라진 뒤 d5가 고립됩니다. d5는 e4/c4를 지배하지만 폰 수비가 없고 백 d4 봉쇄의 대상입니다. 흑 …d4는 해방 돌파, 백은 공간 봉쇄가 목표입니다. c폰이 남은 그림에 고립폰이라고 미리 표시하지 않습니다.','흑의 활동 보상: 고립 d5는 기물의 중앙 배치 공간을 줍니다.|백의 봉쇄: d4를 확보하면 …d4를 막아 흑의 활동을 줄입니다.|교환의 방향: 공격 중기물이 줄면 고립폰의 장기 부담이 커집니다.','백: d4 나이트와 g2 비숍은 d5 및 중앙 칸을 압박합니다. 중앙 룩을 d열에 놓아 폰 수비를 묶습니다.|흑: e4 나이트와 c5/d6 비숍이 활동을 얻을 수 있습니다. 룩은 c/e열의 열린 선을 쓰며 d폰을 단순 수비하는 데만 쓰지 않습니다.','백: d5 → 봉쇄 나이트·g2 비숍·중앙 룩 → 돌파 차단과 유리한 엔드게임.|흑: 왕측 킹과 e4/c4 칸 → 중앙 나이트·비숍·열린 열 룩 → 폰 약점을 활동으로 보상.','흑의 …d4: 고립폰을 전진시켜 중앙 선을 엽니다. 백이 막지 못하면 봉쇄 이점이 사라집니다.|백의 소기물 교환: 흑 공격을 줄이려 합니다. 흑은 폰 약점만 남는 엔드게임으로 갈지 활동을 유지할지 판단합니다.','d5 고립폰 가능성→나이트를 d4 봉쇄 칸에→흑 …d4를 먼저 통제→d5→흑의 공격 소기물 교환→봉쇄 나이트 보존→구조적 우위의 엔드게임','d5 공간·구조 부담→비숍·중앙 룩 활성화→…d4 준비→e4 전초기지·왕측→봉쇄 나이트를 교환→활동 말 전체의 교환 피하기→중앙 돌파가 실현된 활동 국면');
profile('qgd','퀸즈 갬빗 · 중앙 긴장','백은 c4로 d5를 압박하며 더 넓은 중앙을 만들려 하고 흑은 e6–d5의 견고함을 바탕으로 …c5/…e5 해방을 준비합니다. 닫힌 게임 계열이지만 중앙 교환에 따라 열린 선의 포지셔널 싸움으로 바뀝니다.','백 c4–d4와 흑 e6–d5가 맞서는 긴장 구조입니다. 공간은 백이 조금 더 쉽게 얻지만 확정된 우위는 아닙니다. 흑 e6은 d5를 지키는 강점인 동시에 c8 비숍을 막습니다. cxd5 exd5 후 카를스바트, 흑 …c5 교환 후 고립폰 등으로 갈라집니다.','d5 압박: c4·Nc3·Bg5로 흑의 중앙 수비를 묶습니다.|흑의 해방: …c5/…e5가 성공하면 좁은 공간과 비숍 문제가 함께 줄어듭니다.|구조 선택: 교환 전 긴장과 카를스바트 소수 공격은 동일한 국면이 아닙니다.','백: Nc3는 d5/e4, Bg5는 f6 수비 말을 압박합니다. e3가 c1 비숍을 막으므로 먼저 꺼내는 수순의 의미가 큽니다. 중앙 룩은 c/d열 교환 이후 효율이 커집니다.|흑: c8 비숍은 e6에 제한되어 …b6–Bb7, …Bd7 또는 중앙 돌파가 필요합니다. f6 나이트는 d5를 지키며 e4를 통제하는 중요한 말입니다.','백: d5와 f6 수비 말 → c4·Nc3·Bg5 → 중앙 공간 및 e4 돌파 가능성.|흑: 백 d4 중앙 → …c5·…e5와 중앙 룩 → 공간 균형 및 c8 비숍 해방.','흑의 …c5: d4를 공격해 백의 e4 확장을 막습니다. 백은 교환 결과를 계산해야 하며 고립폰이 생길 쪽이 수순에 따라 달라집니다.|백의 cxd5: 카를스바트 구조로 바꾸려 합니다. 흑은 소수 공격에 대비하거나 중앙·왕측 활동으로 반격해야 합니다.','중앙 긴장→c1 비숍·중앙 룩 개선→e4 또는 cxd5 선택→d5·중앙 수비 말→f6 나이트를 유리한 조건에서 교환→활동적인 비숍을 의미 없이 교환하지 않기→공간과 중앙 선을 확보한 국면','e6–d5 방어 구조→c8 비숍 해결→…c5 또는 …e5 준비→d4→백의 공간 활용 소기물 교환→d5 수비 말을 계산 없이 제거하지 않기→해방 돌파 후 자유로운 전개');
profile('carlsbad','카를스바트 · 소수 공격','퀸즈 갬빗 교환 후 백은 퀸사이드 소수 공격이나 중앙 e4 확장을 선택합니다. 흑은 중앙·왕측 활동을 만들어 백의 장기적인 c6 공격을 상쇄합니다. 닫힌 중앙에서 계획을 준비하는 포지셔널 구조입니다.','백 c폰과 흑 e폰이 교환되어 백 a/b 두 폰, 흑 a/b/c 세 폰의 퀸사이드 비대칭이 생깁니다. 흑 c6–d5는 단단하지만 b4–b5 교환 후 c6가 뒤처진 약점이 될 수 있습니다. 약점은 돌파 전부터 확정된 것이 아닙니다. 백 e4와 흑 …c5도 핵심 브레이크입니다.','소수 공격: b4–b5로 흑의 c6 수비를 고정하고 c열의 표적을 만듭니다.|중앙 확장: f3–e4 계획은 백의 기물 배치가 갖춰져야 합니다.|흑의 반격: …Ne4·…f5 또는 …c5로 백에게 퀸사이드만 볼 시간을 주지 않습니다.','백: c열 룩과 b5를 지원하는 나이트가 소수 공격을 돕습니다. 어두운 칸 비숍은 왕측 수비·중앙 통제에 중요합니다.|흑: e4 나이트가 왕측 공격 거점이 됩니다. 나쁜 비숍 여부는 c6–d5 폰과 비숍의 실제 대각선에 달리며 중앙이 열리면 평가가 바뀝니다.','백: 돌파 후 c6 → b폰·c열 룩·나이트 → 고정 약점 또는 폰 획득.|흑: 백 킹·e4 칸 → 나이트·퀸·왕측 룩 또는 …c5 → 왕측 주도권/중앙 해방.','흑의 …c5: c6 약점 자체를 없애려 합니다. 백은 교환 뒤 d5 고립폰이나 활동 변화까지 확인해야 합니다.|흑의 …Ne4와 왕측 활동: 소수 공격에 반대편에서 대응합니다. 백이 왕측 수비를 빼면 장기 계획보다 빠른 킹 공격이 먼저 옵니다.','카를스바트→룩을 c열에·나이트를 돌파 지원 칸에→b4–b5 또는 e4 중 선택→c6 또는 중앙→c6를 지키는 말 교환→왕측 수비 비숍을 성급히 없애지 않기→고정된 약점과 안전한 킹','c6–d5 사슬→나이트를 e4에·룩 활성화→…c5 또는 조건부 …f5→왕측 킹·중앙→백의 소수 공격 지원 말 교환→활동을 가진 공격 나이트 보존→c6 해방 또는 왕측 주도권');
profile('open-sicilian','오픈 시실리안 · 비대칭 중앙','흑은 e5 대칭을 피하고 c폰을 백 d폰과 교환해 중앙 폰 다수와 반열린 c열을 얻습니다. 백은 e4 공간과 빠른 기물 활동을 활용합니다. 반열린 게임의 불균형이 출발점이며 캐슬링 방향과 흑 e폰 배치에 따라 공격 성격이 달라집니다.','백 d폰·흑 c폰이 없어 백은 반열린 d열, 흑은 반열린 c열을 얻습니다. 백 e4가 공간 거점이며 흑 d/e폰이 중앙 자원입니다. 흑 d6가 뒤처진 약점이 되는지는 e폰 배치와 …d5 가능성에 달립니다. 백의 c2 표적은 퀸사이드 캐슬링 때 특히 중요합니다.','c열 압력: …Rc8·…Qc7로 백 퀸사이드에 활동을 만듭니다.|…d5 해방: 흑의 공간 부족을 줄이고 중앙 비숍을 풉니다. 무조건 밀면 중앙 폰이 떨어집니다.|백의 전개 우위: 중앙과 왕측의 활동을 쓰되 흑 반격이 시작될 열도 함께 지킵니다.','백: d4 나이트는 중앙 공간을 쓰지만 …e5에 쫓길 수 있습니다. c3 나이트는 e4를 지키고, 비숍 배치는 흑 e6/e5/g6에 맞춰 고릅니다. 룩은 d열과 공격 선을 활용합니다.|흑: f6 나이트는 e4를 압박합니다. c열 룩이 구조의 혜택을 쓰며 비숍은 e폰·g폰 선택에 따라 e7/c5 또는 g7 등 역할이 크게 달라집니다.','백: 흑 중앙·킹 → 중앙 나이트·비숍·퀸·룩 → 공간을 공격 선과 주도권으로 전환.|흑: c2 및 퀸사이드 킹이 있을 경우 그 주변 → c열 룩·퀸·중앙 비숍 → 침투와 반격.','흑의 …d5: 백의 공간과 공격 시간을 줄입니다. 백이 무시하면 e4 교환으로 중앙 선이 열리고 흑 기물이 활성화됩니다.|백의 왕측 폰 전진: 흑 킹의 수비를 없애려 합니다. 흑은 중앙 반격이나 c열 공격으로 속도를 맞추고 킹 주변 교환을 계산해야 합니다.','e4 공간과 반열린 d열→비숍 전개·킹 안전→상대 배치에 맞는 e5/f5 검토→흑 중앙·킹→핵심 중앙 수비 말 교환→공격 비숍을 대가 없이 내주지 않기→흑 …d5를 통제한 활동 국면','중앙 폰 다수와 c열→퀸측 기물·룩 활성화→…d5 준비, …b5는 안전 확인→c2·백 중앙→백의 강한 중앙 나이트 교환→현재 구조의 핵심 비숍 보존→중앙 해방과 c열 주도권');
profile('sicilian-e6','e6 시실리안 · 유연한 해방','흑은 …e6으로 d5를 지키면서 …d6/…d5, 비숍 전개 위치, 퀸사이드 확장을 유연하게 고릅니다. 백은 공간과 전개 속도로 이러한 준비를 제약합니다. 반열린 c열의 활동과 중앙 해방을 연결하는 구조입니다.','백 e4와 흑 e6·d7 또는 d6의 비대칭입니다. e6은 d5를 지키지만 c8 비숍의 자유를 줄입니다. …d6까지 두면 작은 중앙/헤지호그 계열이 가능하며 백 c4 마로치가 있으면 d5 돌파가 더 어렵습니다. …d5와 …b5가 서로 다른 역할을 합니다.','…d5 준비: e6이 지지하지만 교환 뒤 e6와 중앙 기물의 안전을 계산해야 합니다.|b5 통제: …a6는 백 Nb5/Bb5를 줄이고 …b5를 준비합니다.|전개 유연성의 비용: 수를 미루는 만큼 백의 공격이 빨라질 수 있습니다.','백: d4/c3 나이트가 공간을 쓰며 어두운 칸 비숍은 e6 약점·중앙을 겨냥할 수 있습니다. c4를 두었다면 밝은 칸 비숍 대각선과 d5 통제가 함께 바뀝니다.|흑: c8 비숍은 …b5–Bb7 또는 …d5 이후 활동을 찾습니다. f8 비숍은 e7·c5·b4 중 수순에 맞는 칸을 택합니다. c열 룩과 c7 퀸은 중앙 돌파를 지원합니다.','백: e6/d6와 중앙 칸 → 나이트·중앙 룩·비숍 → …d5 억제와 공간 활용.|흑: e4 및 c2 → 중앙 나이트·c7 퀸·c열 룩 → …d5 해방 또는 퀸사이드 침투.','백의 Nb5: d6/c7을 압박하려 합니다. …a6 또는 기물 전개 수순으로 막아야 하며 허용하면 돌파 준비가 지연됩니다.|백의 e5: f6 나이트와 중앙을 흔듭니다. 흑은 정확한 나이트 이동과 …d5 가능성을 계산해야 합니다.','백 e4 공간→비숍·중앙 룩 개선→e5는 흑 …d5와 함께 계산→e6/d6·중앙→흑의 해방을 지지하는 말 교환→공간 우위를 쓸 소기물 보존→중앙 돌파를 통제한 압박','e6 작은 중앙→c8 비숍과 퀸측 나이트 개선→…d5, 필요하면 …b5 준비→e4·c2→백의 d4 나이트 교환 검토→유일한 활성 비숍을 잃지 않기→…d5가 실현된 중앙 균형');
profile('sicilian-e5','…e5 시실리안 · d5 약점과 활동','흑은 …e5로 d4 나이트를 밀고 활동 공간을 확보하는 대신 d5의 폰 통제와 d6 수비에 부담을 줍니다. 백은 그 칸을 전초기지로 쓰려 하고 흑은 활동과 중앙 반격으로 정적인 약점을 보상합니다.','흑 d6–e5로 d5를 c/e폰이 지킬 수 없는 구멍이 됩니다. d6는 d5에 전진하기 어려우면 뒤처진 약점입니다. 백 e4가 공간을 지키고 Nd5를 지원합니다. …b5는 퀸사이드 공간, …f5/…d5는 조건부 중앙 해방입니다.','d5 전초기지: 백은 그 칸을 지키는 흑 소기물을 교환하고 나이트를 놓으려 합니다.|정적 약점 vs 활동: d6가 약하다고 흑이 자동 불리한 것은 아닙니다. 활동·템포로 수비 부담을 보상합니다.|백의 나이트 경로: …e5에 밀린 말은 b3/f3/a3–c2 등 정확한 갈래에 맞춰 돌아옵니다.','백: d5 나이트는 폰에 쫓기기 어려워 강합니다. 밝은 칸 비숍을 흑 f6 나이트와 교환하는 발상은 실제 배치에 따라 가치가 달라집니다. d열 룩은 d6를 압박합니다.|흑: f6 나이트·e7 비숍이 d5를 다툽니다. 밝은 칸 비숍은 e5폰과 같은 색의 제한을 받지만 대각선이 열리면 가치가 달라집니다. 활성 나이트와 비숍 쌍의 보상은 실제 교환 후에만 말할 수 있습니다.','백: d5와 d6 → 전초기지 나이트·d열 룩 → 장기 봉쇄와 폰 압박.|흑: e4·왕측 또는 퀸측 → 활성 소기물·…b5/…f5 → 백이 약점만 공격하지 못하게 반격.','흑의 …b5: 퀸사이드 공간과 나이트 축출을 노립니다. 백은 약한 칸과 중앙 돌파를 계산해야 하며 방치하면 기물이 밀립니다.|흑의 …d5: d6 약점을 해소합니다. 백은 d5 통제를 유지해야 하며 성공하면 전초기지의 근거가 사라집니다.','e4 대 d6–e5→밀린 나이트의 복귀 경로 마련→흑 …d5를 통제→d5·d6→d5를 지키는 흑 말 교환→전초기지 나이트 성급한 교환 피하기→d5 봉쇄와 d6 압박','d5 구멍·활동 공간→소기물·c열 룩 활성화→…b5, 조건부 …f5/…d5→e4·퀸사이드→백의 d5 나이트 교환→활동의 근거인 말을 폰만 위해 잃지 않기→구조 약점이 해소되거나 보상된 국면');
profile('dragon','드래곤 · 긴 대각선','흑은 g7 비숍의 긴 대각선과 c열을 반격의 중심으로 삼습니다. 백의 유고슬라브 배치에서는 반대편 캐슬링 후 양쪽 폰 공격이 빠른 전술전이 되지만, 같은 편 캐슬링은 다른 성격의 미들게임을 만듭니다.','백 e4 대 흑 d6·g6의 오픈 시실리안입니다. g6는 g7 비숍을 열지만 h파일 공격에 갈고리가 될 수 있습니다. 백 장기 캐슬링 예시에서는 h4–h5와 흑 …b5/…d5, c열 압력이 중요합니다. d6는 중앙 해방이 막힐 때 압박 대상입니다.','g7 비숍 보존: c3 나이트·b2와 퀸사이드 킹에 향하는 대각선이 반격 자원입니다.|h열 열기: 백 h폰 교환과 Bh6는 흑 킹의 방어 선을 없애려 합니다.|공격 속도: 중앙 …d5와 c열 전술을 무시한 왕측 공격은 늦을 수 있습니다.','백: e3 비숍·d2 퀸은 Bh6를 협력하지만 전술을 확인해야 합니다. c3 나이트는 e4 수비 말인 동시에 g7 비숍의 표적입니다. h열 룩은 파일이 열려야 효과가 큽니다.|흑: g7 비숍은 핵심 공격·수비 말입니다. c열 룩과 c6 나이트가 c3/b2를 겨냥합니다. …Rxc3 교환 희생은 백 킹 주변 수비가 깨지는 구체적인 조건에서만 고려합니다.','백: g7 비숍·흑 킹과 h열 → Qd2/Bh6·h폰·룩 → 핵심 수비 말 제거와 킹 공격.|흑: c3 나이트·b2·퀸사이드 킹 → g7 비숍·c열 룩·퀸 → 폰 구조 손상 및 킹 노출.','흑의 …d5: 왕측 공격 전에 중앙을 해방하려 합니다. 백이 h폰만 밀면 중앙 선이 열려 e4와 킹이 위험할 수 있습니다.|흑의 c열 압력: 백의 장기 캐슬링을 공격하려 합니다. 백은 c3의 희생 전술과 b2 수비를 확인해야 합니다.','e4 공간·반대편 킹일 경우→퀸·비숍·h열 룩 개선→h4–h5를 중앙 안정 후 준비→g7 비숍·흑 킹→g7 수비 비숍 교환→중앙과 퀸측의 핵심 수비 말 보존→열린 h열에서 강한 공격','d6·g6와 c열→g7 비숍·c열 룩 활성화→…d5 또는 퀸측 폰 돌파→c3·b2·백 킹→c3 수비 나이트 제거 검토→g7 비숍을 대가 없이 잃지 않기→긴 대각선과 c열이 결합한 반격');
profile('maroczy','마로치 바인드 · d5 통제','백은 c4·e4로 d5를 두 번 통제해 흑의 해방을 억제하고 공간을 얻습니다. 흑은 좁은 공간에서 교환과 정확한 배치로 버틴 뒤 …d5/…b5 돌파를 노립니다. 전형적으로 포지셔널한 반열린 구조입니다.','백 c4/e4가 넓은 공간을 만들고 흑 c폰이 없어 d5의 폰 통제가 약합니다. 백 d폰은 이미 교환되어 반열린 d열을 씁니다. 백 c4는 공간 강점이지만 흑의 …b5 공격 대상이 될 수 있습니다. 흑 …d6 이후 d6가 고정되면 약점이며 …d5가 되면 구조의 의미가 크게 바뀝니다.','바인드 유지: d5를 잡은 두 폰과 기물이 흑의 중앙 돌파를 막습니다.|흑의 교환: 공간이 좁은 쪽은 소기물 교환으로 전개 혼잡을 줄입니다.|…b5 돌파: c4를 흔들어 d5 통제를 간접적으로 줄입니다.','백: 나이트는 d5 전초기지와 c4/e4 수비를 연결합니다. 밝은 칸 비숍은 e4/c4 같은 색 폰에 제한될 수 있어 대각선 선택이 중요합니다. d열 룩은 중앙 봉쇄를 지원합니다.|흑: g7 비숍은 중앙을 압박하지만 폰에 가려지면 활동이 제한됩니다. 나이트는 c4/e4 공격 또는 교환을 찾고 룩은 c열과 돌파 지원에 씁니다.','백: d5·나중의 d6 → 나이트·중앙 룩 → 해방 차단과 장기 압박.|흑: c4/e4 → …b5·나이트·g7 비숍 → 바인드의 지지 폰 제거와 자유로운 중앙.','흑의 …b5: c4폰을 공격합니다. 백은 a4나 기물 통제 등 실제 배치에 맞춰 대비하며 무시하면 중앙 통제가 줄어듭니다.|흑의 …d5: 중앙 봉쇄를 직접 깨려 합니다. 백은 교환 뒤 기물 전술까지 계산해 허용 여부를 판단합니다.','c4/e4 공간→나이트·제한된 비숍 개선→흑 …b5·…d5 억제→d5·d6→돌파를 지원하는 흑 말 교환→공간을 활용할 소기물 전부 교환 피하기→움직임을 제한하는 중앙 봉쇄','좁은 공간과 g7 비숍→나이트·룩의 혼잡 해소→…b5 또는 …d5 준비→c4/e4→백의 활성 소기물 교환→g7 비숍이 유일한 활동 말이면 보존→바인드가 풀린 중앙');
